export function beginnerLesson(slider){return `<div class="wrap xgb-page">
 <section class="xgb-hero"><a class="xgb-back" href="/gradient-boosting/">← Gradient Boosting сабағына</a><div class="eyebrow">XGBOOST / ҚАРАПАЙЫМ ТІЛМЕН</div><h1>Қатені байқа.<br><em>Біртіндеп түзет.</em></h1><div class="xgb-hero-bottom"><p><b>XGBoost</b> — Gradient Boosting идеясын қолданатын құрал. Ол шағын ағаштарды кезекпен қосады. Әр жаңа ағаш <b>ортақ болжамды</b> жақсартуға көмектеседі.</p><span class="xgb-stamp">XG<br><small>BOOST</small></span></div></section>
 <nav class="xgb-nav" aria-label="Сабақ бөлімдері"><a href="#xgb-idea">01 Мысал</a><a href="#xgb-compare">02 Қысқаша</a><a href="#xgb-controls">03 Баптаулар</a><a href="#xgb-lab">04 Өзің байқап көр</a><a href="#xgb-quiz">05 Тексеру</a></nav>
 <section class="xgb-section" id="xgb-idea"><span class="eyebrow">01 / БІР МЫСАЛМЕН ТҮСІНЕЙІК</span><h2>Қанша алма жинаймыз?</h2><p>Модель бақтан <b>3 кг</b> алма жиналады деп болжады. Ал шын мәнінде <b>5 кг</b> жиналды. Болжам 2 кг-ға кем болды.</p><div class="xgb-apple-flow"><div><span>МОДЕЛЬДІҢ БОЛЖАМЫ</span><strong>3 <small>кг</small></strong></div><i>→</i><div><span>ШЫН НӘТИЖЕ</span><strong>5 <small>кг</small></strong></div><i>→</i><div><span>ҚОСУ КЕРЕК</span><strong>+2 <small>кг</small></strong></div></div><p>Жаңа ағаш «болжамға 2 кг қосайық» деп ұсыныс жасасын. Бірден бәрін қоспай, <b>жартысын ғана</b> алсақ:</p><div class="xgb-simple-equation"><span>3 кг</span><b>+</b><span>1 кг</span><b>=</b><strong>4 кг</strong></div><p>Біз 5 кг-ға жақындадық. Келесі ағаш қалған қатені түзетуге көмектеседі. Осылай болжам қадам сайын өзгереді.</p><p class="xgb-takeaway">XGBoost-тың негізі: <b>болжам жаса → қатені байқа → түзету қос.</b></p></section>
 <section class="xgb-section" id="xgb-compare"><span class="eyebrow">02 / АЛДЫҢҒЫ САБАҚПЕН БАЙЛАНЫС</span><h2>Ал XGBoost несімен ерекше?</h2><div class="xgb-prose"><p><b>Gradient Boosting</b> — ағаштарды кезекпен қосып, болжамды жақсарту тәсілі.</p><p><b>XGBoost</b> — осы тәсілді қолданатын дайын кітапхана. Ол жылдам есептеуге және қажетсіз күрделі ағаштарды шектеуге арналған мүмкіндіктер береді.</p></div><p>Қарапайым тілмен: тек қатені азайтуға емес, <b>артық тармақ қоспауға және тым үлкен түзету жасамауға</b> да көңіл бөлеміз.</p><p class="xgb-note">XGBoost әр есепте міндетті түрде ең жақсы нәтиже бермейді. Сапаны модель көрмеген бөлек деректермен тексереміз.</p></section>
 <section class="xgb-section" id="xgb-controls"><span class="eyebrow">03 / ҮШ БАПТАУДЫ БІЛСЕҢ ЖЕТКІЛІКТІ</span><h2>Өзгерісті өзің басқар.</h2><div class="xgb-concepts xgb-plain-controls"><article><span>01</span><h3>Түзетуді ұстамды ету</h3><p>Ағаш ұсынатын өзгерісті тежейді. Мәнін арттырсаң, түзету көбіне кішірейеді.</p><small>Техникалық атауы: λ</small></article><article><span>02</span><h3>Артық тармақ қоспау</h3><p>Жаңа тармақтың пайдасы аз болса, оны қоспаймыз. Мәнін арттырсаң, бөлуге қойылатын талап күшейеді.</p><small>Техникалық атауы: γ</small></article><article><span>03</span><h3>Түзетудің үлесін алу</h3><p>1 болса — толық түзету. 0.5 болса — жартысы. Алма мысалында жартысын алдық.</p><small>Learning rate: η</small></article></div><p class="xgb-note">Алғашқы баптау ағаш ұсынатын түзетуге әсер етеді. Соңғысы дайын түзетудің қанша бөлігін қосатынымызды анықтайды.</p></section>
 <section class="xgb-section" id="xgb-lab"><span class="eyebrow">04 / ЕНДІ ӨЗІҢ БАЙҚАП КӨР</span><h2>Сызықты нүктелерге жақындат.</h2><p>Мұнда ойдан алынған 8 бақтың өнімін болжаймыз. Ақ нүктелер — жиналған алма, сары сызық — модельдің болжамы. Көлденең ось — бақтың шартты белгісі, тік ось — өнім, кг.</p><ol class="xgb-try-steps"><li><b>«Келесі ағаш»</b> батырмасын бас. Сызық қалай өзгерді?</li><li><b>«Ұстамды түзету»</b> мысалын таңда. Бірінші қадамдағы өзгеріс кішірейеді.</li><li><b>«Артық тармақсыз»</b> мысалын таңда. Бұл баптауда бөлу қабылданбайды.</li></ol><div class="xgb-presets" aria-label="Тәжірибе мысалдары"><button class="btn secondary small" data-xgb-preset="basic">Әдеттегі қадам</button><button class="btn secondary small" data-xgb-preset="gentle">Ұстамды түзету</button><button class="btn secondary small" data-xgb-preset="simple">Артық тармақсыз</button></div><div class="xgb-lab"><div class="xgb-lab-title"><strong>АЛМА ӨНІМІН БОЛЖАУ</strong><span>8 бақ · оқу мысалы</span></div><div id="xgb-chart"></div><div class="xgb-legend"><span>● Жиналған алма</span><span>━ Біздің болжам</span></div><div class="xgb-sliders">${slider('xgb-lambda','Түзетуді ұстамды ету · λ',0,10,1,.1)}${slider('xgb-gamma','Артық тармақ қоспау · γ',0,10,0,.1)}${slider('xgb-rate','Түзетудің үлесі · η',.05,1,.3,.05)}</div><div class="xgb-actions"><button id="xgb-add" class="btn small">Келесі ағаш +</button><button id="xgb-reset" class="btn secondary small">Басынан ↻</button><span>Қадам: <b id="xgb-step">1</b> / 20</span><span>Оқыту қатесі: <b id="xgb-mse"></b></span></div><div id="xgb-simple-feedback" aria-live="polite"></div></div><p class="xgb-note">Қате саны аз болған сайын, болжам осы 8 мысалға жақынырақ. Бұл жаңа деректерде де міндетті түрде дәл болады деген сөз емес. Мұнда XGBoost кітапханасының негізгі идеясын көрсететін шағын оқу моделі қолданылған.</p>
 <details class="xgb-advanced" id="xgb-math"><summary>Есеп қалай жасалады? Формулаларды ашу</summary><div class="xgb-advanced-body"><p>Бұл бөлімді өткізіп жіберсең де, негізгі идеяны түсіне аласың.</p><p>Мысалда бір нүктенің шығыны ℓ = ½(ŷ − y)². Бірінші туынды g = ŷ − y қатенің өзгеру бағытын сипаттайды. Екінші туынды h = 1 — қисықтық туралы ақпарат. G және H — осы мәндердің бір жапырақтағы қосындылары.</p><div class="formula">w* = −G / (H + λ)</div><p>w — ағаш ұсынған түзету. Болжамға оның η бөлігі қосылады. Ал бір түйінді екіге бөлудің пайдасы:</p><div class="formula xgb-gain-formula">Gain = ½[Gᴸ²/(Hᴸ+λ) + Gᴿ²/(Hᴿ+λ) − G²/(H+λ)] − γ</div><p>Осы мысалда Gain &gt; 0 болса, бөлу қабылданады. γ — қосымша жапырақтың құны. Оқу моделі бір белгі мен тереңдігі 1 ағаштарды қолданады.</p><div id="xgb-calculation"></div></div></details></section>
 <section class="xgb-section" id="xgb-quiz"><span class="eyebrow">05 / БІР СҰРАҚ</span><h2>Түсінікті болды ма?</h2><div class="quiz-item"><p>«Артық тармақ қоспау» баптауын арттырсақ, не болуы мүмкін?</p><div class="quiz-options"><button data-xgb-answer="wrong">Ағаш барлық тармақты міндетті түрде қосады</button><button data-xgb-answer="correct">Пайдасы аз тармақ қосылмайды</button><button data-xgb-answer="wrong">Ағаштар бір-бірінен тәуелсіз үйренеді</button></div><p id="xgb-feedback" aria-live="polite"></p></div></section>
 <section class="xgb-section xgb-sources"><span class="eyebrow">ТЕРЕҢІРЕК БІЛГІҢ КЕЛСЕ</span><a href="https://xgboost.readthedocs.io/en/stable/tutorials/model.html" target="_blank" rel="noopener">XGBoost ресми түсіндірмесі ↗</a><a href="https://xgboost.readthedocs.io/en/stable/faq.html" target="_blank" rel="noopener">Жиі қойылатын сұрақтар ↗</a></section><div class="xgb-end"><a class="btn secondary" href="/gradient-boosting/">← Gradient Boosting-ке қайту</a><a href="/">Оқу бағытына оралу ↗</a></div></div>`}
